from concepts import EventTime, ItemIdentity, Target, Task
from sprisk import Choice, choose, method
from validation import group_split, random_split, stratified_split, temporal_split


@method(
    decides="split.method",
    name="Train/test split",
    activity="Fair evaluation",
    question="How are rows divided into training and test so the score is fair?",
    applies_when={"task": ["classification", "regression"]},
    decisions=["data.repeated_items"],
    options={
        "temporal": temporal_split,
        "item_groups": group_split,
        "stratified_random": stratified_split,
        "simple_random": random_split,
    },
    source=(
        "Roberts et al. (2017), Ecography 40(8): cross-validation for temporal and grouped "
        "data; scikit-learn User Guide §3.1: GroupShuffleSplit, train_test_split(stratify=y)."
    ),
)
def split_method(
    task: Task,
    event_time: EventTime | None,
    item_identity: ItemIdentity | None,
    target: Target | None,
) -> Choice:
    if event_time:
        return choose(
            "temporal",
            "A time column orders the rows: train on earlier rows, test on later ones. The split "
            "leaves no gap at the cutoff, so a label that looks ahead may share its window "
            "with the first test rows.",
        )
    if item_identity:
        return choose(
            "item_groups",
            "Rows of one item stay on one side, so no item is scored on rows the model saw.",
        )
    if task == "classification" and target:
        return choose(
            "stratified_random",
            "Every row is its own item, and each class keeps its share in train and test.",
        )
    return choose("simple_random", "Every row is its own item.")

from typing import TypedDict

import polars as pl
from sklearn.model_selection import GroupShuffleSplit

from concepts import ItemIdentity
from sprisk import evidence, operator, promise
from validation.settings import Seed, TestFraction

# Enough ids for a person to look one up; the count says how many there are.
SHOWN = 20


class GroupOverlap(TypedDict):
    overlapping: int
    overlapping_groups: list[str]
    train_groups: int
    test_groups: int


@evidence(produces="evaluation.group_overlap", title="Group leakage check")
def group_overlap(
    train: pl.DataFrame, test: pl.DataFrame, group_column: ItemIdentity
) -> GroupOverlap:
    """Counts the groups with rows in both train and test."""
    learned = train[group_column].drop_nulls().unique()
    scored = test[group_column].drop_nulls().unique()
    both = learned.filter(learned.is_in(scored.implode())).sort()
    return {
        "overlapping": both.len(),
        "overlapping_groups": [str(g) for g in both.head(SHOWN).to_list()],
        "train_groups": learned.len(),
        "test_groups": scored.len(),
    }


@promise(needs=group_overlap)
def no_group_overlap(overlap: GroupOverlap) -> tuple[str, str]:
    """No item has rows in both train and test."""
    if overlap["train_groups"] == 0 or overlap["test_groups"] == 0:
        return "inconclusive", "One side has no groups."
    if overlap["overlapping"]:
        shown = ", ".join(overlap["overlapping_groups"][:5])
        return "fail", f"{overlap['overlapping']} items have rows in both train and test: {shown}"
    return "pass", (
        f"No item is in both sides ({overlap['train_groups']} train, "
        f"{overlap['test_groups']} test items)."
    )


@operator(role="split", folds="group", promises=[no_group_overlap])
def group_split(
    data: pl.DataFrame,
    group_column: ItemIdentity,
    test_fraction: TestFraction = 0.2,
    seed: Seed = 42,
) -> dict[str, pl.DataFrame]:
    """Hold out complete entities so the same group never appears in train and test."""
    groups = data[group_column]
    if groups.null_count():
        raise ValueError(
            f"{group_column} has {groups.null_count()} missing values; resolve them first"
        )
    if groups.n_unique() < 2:
        raise ValueError(f"{group_column} needs at least two distinct groups")
    splitter = GroupShuffleSplit(n_splits=1, test_size=test_fraction, random_state=seed)
    train_rows, test_rows = next(splitter.split(range(data.height), groups=groups.to_list()))
    train, test = data[sorted(train_rows)], data[sorted(test_rows)]
    if train.is_empty() or test.is_empty():
        raise ValueError(f"split gave {train.height} train and {test.height} test rows")
    return {"train": train, "test": test}

from typing import TypedDict

import polars as pl

from concepts import EventTime, ItemIdentity
from sprisk import evidence, operator, promise
from validation.settings import TestFraction


class TimeOrder(TypedDict):
    not_later_test_rows: int
    latest_train: str
    earliest_test: str
    train_rows: int
    test_rows: int


@evidence(produces="evaluation.time_order", title="Time order check")
def time_order(train: pl.DataFrame, test: pl.DataFrame, time_column: EventTime) -> TimeOrder:
    """Counts the test rows that are not later than the latest train row."""
    for table, side in ((train, "train"), (test, "test")):
        missing = table[time_column].null_count()
        if missing:
            raise ValueError(f"{missing} {side} rows have no {time_column}")
    latest = train[time_column].max()
    if latest is None or test.is_empty():
        raise ValueError(f"one side has no {time_column} values to order")
    return {
        "not_later_test_rows": test.filter(pl.col(time_column) <= latest).height,
        "latest_train": str(latest),
        "earliest_test": str(test[time_column].min()),
        "train_rows": train.height,
        "test_rows": test.height,
    }


@promise(needs=time_order)
def test_after_train(order: TimeOrder) -> tuple[str, str]:
    """Every test row is later than the latest train row."""
    latest = order["latest_train"]
    if order["not_later_test_rows"]:
        return "fail", f"{order['not_later_test_rows']} test rows are not later than {latest}."
    return "pass", f"Every test row is later than {latest}, the latest train row."


@operator(role="split", folds="time", promises=[test_after_train])
def temporal_split(
    data: pl.DataFrame,
    time_column: EventTime,
    test_fraction: TestFraction = 0.2,
    group_column: ItemIdentity | None = None,
) -> dict[str, pl.DataFrame]:
    """Split by time. Every train row is strictly earlier than every test row."""
    times = data[time_column]
    if times.null_count():
        raise ValueError(f"{time_column} has {times.null_count()} missing values")
    cutoff = times.quantile(1 - test_fraction, interpolation="lower")
    is_test = pl.col(time_column) >= cutoff
    train, test = data.filter(~is_test), data.filter(is_test)
    # Purge: train loses every row of an item that is also in test.
    if group_column is not None:
        train = train.filter(~pl.col(group_column).is_in(test[group_column].implode()))
    if train.is_empty() or test.is_empty():
        raise ValueError(f"split gave {train.height} train and {test.height} test rows")
    return {"train": train, "test": test}

